INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'DS.BASIC','数据结构基础与复杂度','算法的时间复杂度衡量基本操作次数随输入规模的增长；空间复杂度衡量额外存储增长，分析时区分最坏、平均与最好情况。',ARRAY['数据结构基础'],2,1 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='DS' AND p.code='DS.LINEAR' ON CONFLICT(code) DO NOTHING;
INSERT INTO learning_assets(user_id,kind,point_id,title,payload,status,is_public,seed_key) SELECT kb.user_id,'material',p.id,'数据结构基础与复杂度：讲解与例题','{"Stem": "算法的时间复杂度衡量基本操作次数随输入规模的增长；空间复杂度衡量额外存储增长，分析时区分最坏、平均与最好情况。", "Explanation": "例题：单层遍历 n 个元素执行 n 次访问，时间复杂度为 O(n)。", "Source": "408 基础课程 v1 · 项目原创概念讲义，非官方考纲", "Answer": -1, "EstimatedMinutes": 10, "Difficulty": 1}'::jsonb,'ready',true,'DS.BASIC:material:v1' FROM knowledge_bases kb,exam408_knowledge_points p WHERE kb.is_system AND p.code='DS.BASIC' ON CONFLICT(seed_key) DO NOTHING;
INSERT INTO learning_assets(user_id,kind,point_id,title,payload,status,is_public,seed_key) SELECT kb.user_id,'question',p.id,'数据结构基础与复杂度：基础练习','{"Stem": "两层循环各独立执行 n 次，时间复杂度是？", "Options": ["O(n²)", "O(n)", "O(log n)", "O(1)"], "Answer": 0, "Explanation": "独立嵌套循环执行 n×n 次基本操作。", "Source": "408 基础课程 v1 · 项目原创练习，非历年真题", "AnswerOrigin": "source", "QuestionOrigin": "editorial", "Difficulty": 1, "EstimatedMinutes": 3}'::jsonb,'ready',true,'DS.BASIC:question:v1' FROM knowledge_bases kb,exam408_knowledge_points p WHERE kb.is_system AND p.code='DS.BASIC' ON CONFLICT(seed_key) DO NOTHING;
INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'DS.SEQ','顺序表与链表','顺序表连续存储，可按下标随机访问；链表依靠指针连接，定位需遍历，已知前驱后插入可在常数时间完成。',ARRAY['顺序表'],2,2 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='DS' AND p.code='DS.LINEAR' ON CONFLICT(code) DO NOTHING;
