INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'DS.STACK','栈、队列与数组','栈遵循后进先出，队列遵循先进先出；循环队列需要区分空与满，常预留一个存储位置。数组按行优先或列优先映射线性地址。',ARRAY['栈、队列'],2,3 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='DS' AND p.code='DS.LINEAR' ON CONFLICT(code) DO NOTHING;
