INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'DS.BINARY','二叉树遍历与线索','二叉树每个结点至多有两个有序子树；先序为根左右，中序为左根右，后序为左右根。线索二叉树利用空指针保存遍历前驱或后继。',ARRAY['二叉树遍历'],2,1 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='DS' AND p.code='DS.TREE' ON CONFLICT(code) DO NOTHING;
