INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'OS.SYNC','进程同步与互斥','临界资源需要互斥访问，信号量 P/V 操作可表达互斥与先后同步；必须防止遗漏释放和错误的操作顺序。管程将共享状态与同步操作封装。',ARRAY['进程同步'],2,4 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='OS' AND p.code='OS.PROCESS' ON CONFLICT(code) DO NOTHING;
