INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'OS.VIRTUAL','虚拟内存与页面置换','虚拟内存按需调页，缺页需要调入页面；FIFO、LRU、Clock 用不同规则选择淘汰页。局部性与工作集影响缺页率，抖动会严重降低吞吐。',ARRAY['虚拟内存'],2,2 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='OS' AND p.code='OS.MEMORY' ON CONFLICT(code) DO NOTHING;
