INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'OS.FILES','文件系统与目录','文件系统管理文件、目录、元数据和访问控制；连续、链接与索引分配的随机访问和扩展代价不同。硬链接指向同一 inode，符号链接记录路径。',ARRAY['文件系统'],2,1 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='OS' AND p.code='OS.FILE' ON CONFLICT(code) DO NOTHING;
