INSERT INTO exam408_knowledge_points(subject_id,parent_id,code,name,description,keywords,level,sort_order) SELECT s.id,p.id,'CN.TCP','TCP 可靠传输与拥塞控制','TCP 是面向连接的可靠字节流，使用序号、累计确认、重传和窗口。流量控制保护接收方，拥塞控制保护网络；连接建立通常用三次握手。',ARRAY['TCP 可靠传输'],2,2 FROM exam408_subjects s,exam408_knowledge_points p WHERE s.code='CN' AND p.code='CN.TRANSPORT' ON CONFLICT(code) DO NOTHING;
