BEGIN;
-- A locked service identity owns the corpus; it cannot authenticate and is not a human administrator.
ALTER TABLE knowledge_bases ADD COLUMN is_system boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX knowledge_bases_single_system ON knowledge_bases(is_system) WHERE is_system;
-- Retain an existing public corpus when upgrading rather than create a second one.
UPDATE knowledge_bases SET is_system=true WHERE id=(SELECT id FROM knowledge_bases WHERE is_public ORDER BY created_at,id LIMIT 1);
SELECT '40800000-0000-4000-8000-000000000002','40800000-0000-4000-8000-000000000001','408 系统公共知识库','四科基础课程与原创练习；非官方逐年考纲或历年真题',true,true WHERE NOT EXISTS(SELECT 1 FROM knowledge_bases WHERE is_system);
ALTER TABLE learning_assets ADD COLUMN is_public boolean NOT NULL DEFAULT false;
ALTER TABLE learning_assets ADD COLUMN seed_key text UNIQUE;
CREATE INDEX learning_assets_public ON learning_assets(kind,point_id) WHERE is_public;

SELECT kb.user_id,kb.id,p.name,'knowledge_point',p.description,'canonical',1 FROM knowledge_bases kb CROSS JOIN exam408_knowledge_points p WHERE kb.is_system ON CONFLICT(knowledge_base_id,name,entity_type) DO NOTHING;
SELECT e.user_id,p.id,e.id,1 FROM knowledge_entities e JOIN knowledge_bases kb ON kb.id=e.knowledge_base_id AND kb.is_system JOIN exam408_knowledge_points p ON p.name=e.name WHERE e.entity_type='knowledge_point' ON CONFLICT DO NOTHING;
SELECT kb.user_id,kb.id,a.id,b.id,r.relation_type,'canonical',1 FROM exam408_knowledge_point_relations r CROSS JOIN knowledge_bases kb JOIN knowledge_entities a ON a.knowledge_base_id=kb.id AND a.name=(SELECT name FROM exam408_knowledge_points WHERE id=r.from_point_id) AND a.entity_type='knowledge_point' JOIN knowledge_entities b ON b.knowledge_base_id=kb.id AND b.name=(SELECT name FROM exam408_knowledge_points WHERE id=r.to_point_id) AND b.entity_type='knowledge_point' WHERE kb.is_system AND NOT EXISTS(SELECT 1 FROM knowledge_relations x WHERE x.from_entity_id=a.id AND x.to_entity_id=b.id AND x.relation_type=r.relation_type AND x.evidence_chunk_id IS NULL);
COMMIT;
